class Solution {
    public int maxCoins(int[] nums) {
        java.util.ArrayList<Integer> positive = new java.util.ArrayList<>();
        for (int num : nums) {
            if (num > 0) {
                positive.add(num);
            }
        }
        int k = positive.size();
        if (k == 0) {
            return 0;
        }
        int[] values = new int[k + 2];
        values[0] = 1;
        values[k + 1] = 1;
        for (int i = 0; i < k; i++) {
            values[i + 1] = positive.get(i);
        }
        int[][] dp = new int[k + 2][k + 2];
        for (int length = 1; length <= k; length++) {
            for (int left = 1; left + length - 1 <= k; left++) {
                int right = left + length - 1;
                for (int last = left; last <= right; last++) {
                    int coins = dp[left][last - 1]
                            + values[left - 1] * values[last] * values[right + 1]
                            + dp[last + 1][right];
                    dp[left][right] = Math.max(dp[left][right], coins);
                }
            }
        }
        return dp[1][k];
    }
}

class Solution {
    public int maxCoins(int[] nums) {
        int n = nums.length;
        int size = n + 2;
        int[] values = new int[size];
        values[0] = 1;
        values[size - 1] = 1;
        for (int i = 0; i < n; i++) {
            values[i + 1] = nums[i];
        }
        int[] dp = new int[size * size];
        for (int gap = 2; gap < size; gap++) {
            for (int left = 0; left + gap < size; left++) {
                int right = left + gap;
                int best = 0;
                for (int last = left + 1; last < right; last++) {
                    int coins = dp[index(left, last, size)]
                            + values[left] * values[last] * values[right]
                            + dp[index(last, right, size)];
                    best = Math.max(best, coins);
                }
                dp[index(left, right, size)] = best;
            }
        }
        return dp[index(0, size - 1, size)];
    }

    private int index(int left, int right, int size) {
        return left * size + right;
    }
}
